const source=`// Verify only the recorded actual history. No candidate moves or future lines.
const calls=load("calls"),moves=[],checks=[],b={};
for(const col of cols)for(let y=1;y<=9;y++)b[col+y]=".";
function check(call){const differences=Object.keys(b).filter(p=>b[p]!==call.board[p]);const cap=call.text.match(/Captured by Black: (\\d+); by White: (\\d+)/);checks.push({actualMoves:moves.length,boardMatches:differences.length===0,differences,captureMatches:cap&&cap[1]==="0"&&cap[2]==="0"});}
check(calls[0]);
for(const call of calls.slice(1)){
  if(call.kind!=="play")throw Error("Unexpected call");
  const opp=call.text.match(/Your opponent played ([A-HJ][1-9])\\./);
  const white=opp?opp[1]:/Your opponent passed/.test(call.text)?"pass":null;
  if(!white)throw Error("Missing actual White move");
  for(const [color,p] of [["X",call.move],["O",white]]){
    if(p!=="pass"){if(b[p]!==".")throw Error("Actual occupied point "+p);b[p]=color;
      if(inspect(b).groups.some(g=>g.liberties.length===0))throw Error("Unexpected zero-liberty group in capture-free actual history");}
    moves.push({number:moves.length+1,color:color==="X"?"B":"W",move:p});
  }
  check(call);
}
if(checks.some(c=>!c.boardMatches||!c.captureMatches))throw Error("Replay mismatch");
const inv=inspect(b),stones={B:0,W:0},territory={B:0,W:0,neutral:0};
for(const c of Object.values(b))if(c==="X")stones.B++;else if(c==="O")stones.W++;
